export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === '.' && !inQuotes) {
      parts.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  parts.push(current);
  return parts;
}

