### Changes Made in `src/utils/parse-config.ts`

1. **`parseSegments` Helper:**
   Introduced a helper to parse property names and extract numeric bracket indices (`/[(\d+)]/g`):
   ```ts
   interface PathSegment {
     key: string | number;
     isIndex: boolean;
   }

   function parseSegments(part: string): PathSegment[] {
     const segments: PathSegment[] = [];
     const bracketRegex = /\[(\d+)\]/g;
     const firstBracket = part.indexOf('[');

     if (firstBracket === -1) {
       segments.push({ key: part, isIndex: false });
       return segments;
     }

     const prop = part.slice(0, firstBracket);
     if (prop.length > 0) {
       segments.push({ key: prop, isIndex: false });
     }

     let match: RegExpExecArray | null;
     while ((match = bracketRegex.exec(part)) !== null) {
       segments.push({ key: parseInt(match[1], 10), isIndex: true });
     }

     return segments;
   }
   ```

2. **Array vs. Object Initialization in `parseConfig`:**
   Flattened the segments using `splitKey(key).flatMap(parseSegments)` and dynamically initialized intermediate containers to `[]` when `nextSeg.isIndex` is true, or `{}` otherwise:
   ```ts
   for (let i = 0; i < segments.length - 1; i++) {
     const seg = segments[i];
     const nextSeg = segments[i + 1];

     if (current[seg.key] === undefined) {
       current[seg.key] = nextSeg.isIndex ? [] : {};
     }
     current = current[seg.key];
   }

   const lastSeg = segments[segments.length - 1];
   current[lastSeg.key] = value;
   ```

