  const bracketRegex = /\[(\d+)\]/g;
  const firstBracket = part.indexOf('[');

  if (firstBracket === -1) {
    segments.push({ key: part, isIndex: false });
    return segments;
  }

  const prop = part.slice(0, firstBracket);
  if (prop.length > 0) {
    segments.push({ key: prop, isIndex: false });
  }

  let match: RegExpExecArray | null;
  while ((match = bracketRegex.exec(part)) !== null) {
    segments.push({ key: parseInt(match[1], 10), isIndex: true });
  }

  return segments;
}

function extractReferences(value: any): string[] {
  const refs: string[] = [];
  if (typeof value === 'string') {
    const regex = /\$\{([^}]+)\}/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(value)) !== null) {
      refs.push(match[1].trim());
    }
  } else if (Array.isArray(value)) {
    for (const item of value) {
      refs.push(...extractReferences(item));
    }
  } else if (value !== null && typeof value === 'object') {
    for (const val of Object.values(value)) {
      refs.push(...extractReferences(val));
    }
  }
  return refs;
}

function validateCircularReferences(raw: Record<string, any>): void {
  const visitedKeys = new Set<string>();
  const resolvedKeys = new Set<string>();

  function checkCircular(key: string): void {
    if (visitedKeys.has(key)) {
      throw new ConfigError('Circular reference detected');
    }
    if (resolvedKeys.has(key)) {
      return;
    }
    if (!(key in raw)) {
      return;
    }

    visitedKeys.add(key);

    const value = raw[key];
    const refs = extractReferences(value);
    for (const ref of refs) {
      checkCircular(ref);
    }

    visitedKeys.delete(key);
    resolvedKeys.add(key);
  }

  for (const key of Object.keys(raw)) {
    checkCircular(key);
  }
}

/**
 * Parses a flat record of key paths and values into a structured configuration object.
 * Supports dot notation, quoted keys, and bracketed array indices.
 *
 * @param raw - The raw configuration key-value pairs to parse.
 * @returns The parsed nested configuration object or array structure.
 * @throws {ConfigError} If a circular reference is detected among configuration values.
 */
export function parseConfig(raw: Record<string, any>): Record<string, any> {
  validateCircularReferences(raw);

  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const segments = splitKey(key).flatMap(parseSegments);

    if (segments.length === 0) {
      continue;
    }

    let current: any = result;

    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      const nextSeg = segments[i + 1];

      if (current[seg.key] === undefined) {
        current[seg.key] = nextSeg.isIndex ? [] : {};
      }
      current = current[seg.key];
    }

    const lastSeg = segments[segments.length - 1];
    current[lastSeg.key] = value;
  }

  return result;
}

